def tr(o):
    if isinstance(o, str): return VI.get(o, o)
    if isinstance(o, dict): return {k: tr(v) for k, v in o.items()}
    if isinstance(o, list): return [tr(v) for v in o]
    if isinstance(o, tuple): return tuple(tr(v) for v in o)
    return o


L = tr(copy.deepcopy(data.LANGS["en"]))
